package ru.funpay.tools;

import android.app.*;
import android.content.*;
import android.os.Bundle;
import android.graphics.Typeface;
import android.graphics.drawable.*;
import android.view.*;
import android.widget.*;
import com.google.zxing.*;
import com.google.zxing.common.HybridBinarizer;
import com.google.zxing.integration.android.IntentIntegrator;
import org.json.JSONObject;
import java.io.*;

public final class WelcomeActivity extends Activity {
    Settings prefs;Palette p;Typeface font;LinearLayout body;final QrTransfer transfer=new QrTransfer();JSONObject pending;
    int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
    TextView text(String value,int size,int color){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(color);t.setTypeface(font);t.setIncludeFontPadding(false);t.setLineSpacing(dp(3),1.05f);t.setPadding(0,dp(6),0,dp(6));return t;}
    Button button(String label,int resource,Runnable run){Button b=new Button(this);b.setText(label);b.setAllCaps(false);b.setTextSize(14);b.setTypeface(Palette.weight(font,500));b.setTextColor(p.text);b.setIncludeFontPadding(false);b.setTextAlignment(View.TEXT_ALIGNMENT_GRAVITY);b.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);b.setPadding(dp(16),dp(12),dp(16),dp(12));b.setMinHeight(dp(52));b.setStateListAnimator(null);GradientDrawable bg=new GradientDrawable();bg.setColor(p.surface);bg.setCornerRadius(dp(12));bg.setStroke(dp(1),p.line);b.setBackground(new RippleDrawable(android.content.res.ColorStateList.valueOf((p.accent&0xffffff)|0x22000000),bg,null));Drawable icon=getDrawable(resource).mutate();icon.setTint(p.accent);icon.setBounds(0,0,dp(22),dp(22));b.setCompoundDrawablesRelative(icon,null,null,null);b.setCompoundDrawablePadding(dp(12));b.setOnClickListener(v->run.run());LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,dp(6),0,dp(6));body.addView(b,lp);return b;}
    @Override public void onCreate(Bundle saved){super.onCreate(saved);prefs=new Settings(this);if(new SessionStore(this).read()!=null&&getSharedPreferences("onboarding",0).getBoolean("complete",false)&&!getIntent().getBooleanExtra("configure",false)){startActivity(new Intent(this,MainActivity.class));finish();return;}if(saved!=null){transfer.id=saved.getString("qr_id","");transfer.total=saved.getInt("qr_total");for(int i=1;i<=transfer.total;i++)if(saved.containsKey("qr_"+i))transfer.chunks.put(i,saved.getString("qr_"+i));}String raw=getSharedPreferences("onboarding",0).getString("pending","");try{if(!raw.isEmpty())pending=new JSONObject(raw);}catch(Exception ignored){}render();AppUpdates.check(this,false);}
    TextView centered(String value,int size,int color){TextView t=text(value,size,color);t.setGravity(Gravity.CENTER);t.setTextAlignment(View.TEXT_ALIGNMENT_CENTER);return t;}
    void space(int height){body.addView(new View(this),new LinearLayout.LayoutParams(1,dp(height)));}
    void primary(Button button){GradientDrawable bg=new GradientDrawable();bg.setColor(p.accent);bg.setCornerRadius(dp(14));button.setBackground(new RippleDrawable(android.content.res.ColorStateList.valueOf(0x22ffffff),bg,null));int ink=p.dark?p.bg:android.graphics.Color.WHITE;button.setTextColor(ink);button.setCompoundDrawablesRelative(null,null,null,null);button.setGravity(Gravity.CENTER);button.setTextAlignment(View.TEXT_ALIGNMENT_CENTER);button.setTypeface(Palette.weight(font,650));button.setMinHeight(dp(56));}
    void link(String label,Runnable click){TextView t=centered(label,13,p.muted);t.setMinimumHeight(dp(48));t.setPadding(dp(8),dp(14),dp(8),dp(14));t.setFocusable(true);t.setClickable(true);t.setOnClickListener(v->click.run());body.addView(t,new LinearLayout.LayoutParams(-1,-2));}
    void enter(){if(new SessionStore(this).read()==null)return;if(pending!=null){stopService(new Intent(this,PresenceService.class));PeriodicPresence.schedule(this,false);prefs.serviceBeat(false);prefs.save(pending);prefs.applyImportedAppearance(pending);getSharedPreferences("onboarding",0).edit().remove("pending").apply();}getSharedPreferences("onboarding",0).edit().putBoolean("complete",true).apply();startActivity(new Intent(this,MainActivity.class));finish();}
    void login(){boolean switching=new SessionStore(this).read()!=null;if(switching){stopService(new Intent(this,PresenceService.class));PeriodicPresence.schedule(this,false);}startActivityForResult(new Intent(this,SiteActivity.class).putExtra("path","/account/login").putExtra("login",true).putExtra("switchAccount",switching),10);}
    void transferOptions(){new AlertDialog.Builder(this).setTitle("Перенести настройки").setItems(new String[]{"QR из изображения","Файл .fpconfig"},(d,i)->{if(i==0)startActivityForResult(new Intent(Intent.ACTION_GET_CONTENT).setType("image/*"),31);else startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE),30);}).setNegativeButton("Отмена",null).show();}
    void render(){
        p=prefs.palette();font=Palette.typeface(this,prefs.font());getWindow().setStatusBarColor(p.bg);getWindow().setNavigationBarColor(p.bg);getWindow().getDecorView().setSystemUiVisibility(p.dark?0:View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);
        LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(android.graphics.Color.TRANSPARENT);root.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(i.getSystemWindowInsetLeft(),i.getSystemWindowInsetTop(),i.getSystemWindowInsetRight(),i.getSystemWindowInsetBottom());return i;});
        ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setGravity(Gravity.CENTER_VERTICAL);body.setPadding(dp(28),dp(32),dp(28),dp(32));scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,-1));
        LinearLayout identity=new LinearLayout(this);identity.setOrientation(LinearLayout.VERTICAL);identity.setGravity(Gravity.CENTER);ImageView logo=new ImageView(this);logo.setImageResource(R.drawable.brand_mark);identity.addView(logo,new LinearLayout.LayoutParams(dp(42),dp(42)));TextView brand=centered("FunPay Pocket",15,p.text);brand.setTypeface(Palette.weight(font,650));brand.setPadding(0,dp(10),0,0);identity.addView(brand);body.addView(identity,new LinearLayout.LayoutParams(-1,-2));space(24);
        JSONObject session=new SessionStore(this).read();TextView title=centered(session==null?"Вход в FunPay":"Всё готово",28,p.text);title.setTypeface(Palette.weight(font,650));body.addView(title);body.addView(centered(session==null?"Подключите аккаунт, чтобы открыть чаты и управление лотами.":"Аккаунт подключён. Можно начинать.",14,p.muted));space(24);
        Button signin=button(session==null?"Продолжить с FunPay":"Открыть приложение",R.drawable.ic_ui_user,session==null?this::login:this::enter);primary(signin);
        TextView accountCaption=centered(session==null?"Вход на funpay.com":session.optString("name","Аккаунт FunPay"),12,p.muted);accountCaption.setPadding(0,dp(2),0,0);body.addView(accountCaption,new LinearLayout.LayoutParams(-1,-2));space(40);
        LinearLayout page=body;
        LinearLayout transferSection=new LinearLayout(this);transferSection.setOrientation(LinearLayout.VERTICAL);transferSection.setPadding(dp(20),dp(20),dp(20),dp(8));transferSection.setTag("auth-transfer-section");
        GradientDrawable sectionBackground=new GradientDrawable();sectionBackground.setColor(p.surface);sectionBackground.setCornerRadius(dp(p.panelRadius));transferSection.setBackground(sectionBackground);
        page.addView(transferSection,new LinearLayout.LayoutParams(-1,-2));body=transferSection;
        TextView transferHeading=text("Настройки расширения",14,p.text);transferHeading.setTypeface(Palette.weight(font,650));transferHeading.setPadding(0,0,0,0);body.addView(transferHeading);space(16);
        LinearLayout qr=new LinearLayout(this);qr.setGravity(Gravity.CENTER);qr.setPadding(dp(16),dp(14),dp(16),dp(14));qr.setMinimumHeight(dp(56));qr.setContentDescription("Перенести настройки по QR");qr.setFocusable(true);qr.setClickable(true);qr.setOnClickListener(v->{transfer.reset();scan();});GradientDrawable outline=new GradientDrawable();outline.setColor(p.bg);outline.setCornerRadius(dp(p.radius));outline.setStroke(dp(1),p.line);qr.setBackground(new RippleDrawable(android.content.res.ColorStateList.valueOf((p.accent&0xffffff)|0x22000000),outline,null));
        LinearLayout qrGroup=new LinearLayout(this);qrGroup.setGravity(Gravity.CENTER);qrGroup.setTag("auth-qr-group");ImageView glyph=new ImageView(this);glyph.setImageResource(R.drawable.ic_ui_qr);glyph.setImageTintList(android.content.res.ColorStateList.valueOf(p.accent));glyph.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);qrGroup.addView(glyph,new LinearLayout.LayoutParams(dp(20),dp(20)));TextView qrCaption=text("Перенести по QR",14,p.text);qrCaption.setTypeface(Palette.weight(font,550));qrCaption.setPadding(dp(10),0,0,0);qrCaption.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);qrGroup.addView(qrCaption);qr.addView(qrGroup,new LinearLayout.LayoutParams(-2,-2));body.addView(qr,new LinearLayout.LayoutParams(-1,-2));
        if(pending!=null){TextView ready=centered(new SessionStore(this).read()==null?"Настройки сохранены на телефоне.\nПрименятся после входа.":"Настройки сохранены на телефоне.\nПрименятся при открытии приложения.",12,p.muted);body.addView(ready);link("Удалить сохранённые настройки",()->{pending=null;transfer.reset();getSharedPreferences("onboarding",0).edit().remove("pending").apply();render();});}else if(transfer.total>0)body.addView(centered("Прочитано QR: "+transfer.chunks.size()+" из "+transfer.total,12,p.accent));
        space(4);link("Другие способы переноса",this::transferOptions);body=page;if(session!=null)link("Войти в другой аккаунт",this::login);if(UpdateInstaller.hasPending(this))link("Установить скачанное обновление",()->UpdateInstaller.resume(this));setContentView(AppearanceBackground.wrap(this,root,p,prefs));
    }
    @Override protected void onResume(){super.onResume();if(prefs!=null&&UpdateInstaller.hasPending(this))render();}
    @Override protected void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);out.putString("qr_id",transfer.id);out.putInt("qr_total",transfer.total);for(var chunk:transfer.chunks.entrySet())out.putString("qr_"+chunk.getKey(),chunk.getValue());}
    void scan(){new IntentIntegrator(this).setDesiredBarcodeFormats(IntentIntegrator.QR_CODE).setPrompt("Наведите камеру на QR настроек в расширении").setOrientationLocked(false).setBeepEnabled(false).initiateScan();}
    void receive(String raw){try{JSONObject value=transfer.accept(raw);if(value!=null)confirm(value);else{render();new AlertDialog.Builder(this).setTitle("QR принят").setMessage("Прочитано "+transfer.chunks.size()+" из "+transfer.total).setPositiveButton("Следующий QR",(d,w)->scan()).setNegativeButton("Позже",null).show();}}catch(Exception e){error(e.getMessage());}}
    void confirm(JSONObject value){new AlertDialog.Builder(this).setTitle("Сохранить настройки на телефоне?").setMessage("После входа эти настройки будут применены к подключённому аккаунту. Автоматизация останется остановленной.").setPositiveButton("Сохранить",(d,w)->{pending=value;getSharedPreferences("onboarding",0).edit().putString("pending",value.toString()).apply();render();}).setNegativeButton("Отмена",null).show();}
    void error(String value){new AlertDialog.Builder(this).setTitle("Не удалось прочитать").setMessage(value).setPositiveButton("Готово",null).show();}
    @Override protected void onActivityResult(int code,int result,Intent data){super.onActivityResult(code,result,data);var qr=IntentIntegrator.parseActivityResult(code,result,data);if(qr!=null){if(qr.getContents()!=null)receive(qr.getContents());return;}if(code==10){render();return;}if(result!=RESULT_OK||data==null||data.getData()==null)return;try{if(code==30){try(InputStream input=getContentResolver().openInputStream(data.getData());ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[4096];int n;while((n=input.read(b))!=-1){if(out.size()+n>2*1024*1024)throw new IOException("Файл больше 2 МБ");out.write(b,0,n);}confirm(Settings.decode(out.toString("UTF-8")));}}else if(code==31){android.graphics.BitmapFactory.Options o=new android.graphics.BitmapFactory.Options();o.inJustDecodeBounds=true;try(InputStream in=getContentResolver().openInputStream(data.getData())){android.graphics.BitmapFactory.decodeStream(in,null,o);}o.inSampleSize=Math.max(1,Math.max(o.outWidth,o.outHeight)/1800);o.inJustDecodeBounds=false;android.graphics.Bitmap bitmap;try(InputStream in=getContentResolver().openInputStream(data.getData())){bitmap=android.graphics.BitmapFactory.decodeStream(in,null,o);}if(bitmap==null)throw new IOException("Нужна картинка с QR");int w=bitmap.getWidth(),h=bitmap.getHeight();int[] pixels=new int[w*h];bitmap.getPixels(pixels,0,w,0,0,w,h);bitmap.recycle();java.util.Map<DecodeHintType,Object> hints=new java.util.EnumMap<>(DecodeHintType.class);hints.put(DecodeHintType.TRY_HARDER,true);hints.put(DecodeHintType.POSSIBLE_FORMATS,java.util.Collections.singletonList(BarcodeFormat.QR_CODE));String resultText;try{resultText=new MultiFormatReader().decode(new BinaryBitmap(new HybridBinarizer(new RGBLuminanceSource(w,h,pixels))),hints).getText();}catch(NotFoundException e){hints.put(DecodeHintType.PURE_BARCODE,true);resultText=new MultiFormatReader().decode(new BinaryBitmap(new HybridBinarizer(new RGBLuminanceSource(w,h,pixels))),hints).getText();}receive(resultText);}}catch(Exception e){error(e instanceof NotFoundException?"QR на изображении не найден":e.getMessage());}}
}
